input.content:
package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = translate(word)
	}
	return strings.Join(words, " ")
}

func translate(word string) string {
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}
	for i := 1; i < len(word); i++ {
		if isVowel(word[i]) {
			return word[i:] + word[:i] + "ay"
		}
		if word[i] == 'y' {
			// Rule 4: y acts as a vowel after a consonant cluster.
			return word[i:] + word[:i] + "ay"
		}
		if word[i] == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			// Rule 3: include the "qu" in the moved prefix.
			return word[i+2:] + word[:i+2] + "ay"
		}
	}
	return word + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

